mapper.sql:
WHERE 1=1
AND a.entity_type=#{q.entityType}
AND a.action=#{q.action}
AND a.actor_id=#{q.actorId}

  AND (LOCATE(#{q.keyword}, a.detail)>0 OR CAST(a.entity_id AS CHAR)=#{q.keyword})

AND a.created_at >= CONCAT(#{q.startDate}, ' 00:00:00')
AND a.created_at <= CONCAT(#{q.endDate}, ' 23:59:59')
